public inherited sharing class ScopedUserDirectory57 {
 public static User chosen;
 public static Integer selectedCount;
 public static void choose(Id wanted) {
  Set<Id> ids=new Set<Id>{wanted};
  List<User> rows=Database.query('SELECT Id,LastName FROM User WHERE Id IN :ids');
  selectedCount=rows.size();chosen=rows.isEmpty()?null:rows[0];
 }
 public static User chosenOrSelf(){if(chosen==null)choose(UserInfo.getUserId());return chosen;}
}

